#[derive(Args, Debug)]
struct RunArgs {
    /// Force deep scan with all available probes
    #[arg(long)]
    deep: bool,

    /// Activity sampling window in milliseconds (0 uses lifetime CPU averages)
    #[arg(long, default_value_t = 500, value_parser = clap::value_parser!(u64).range(0..=60_000))]
    window_ms: u64,

    /// Render the TUI inline (preserves scrollback) instead of using the alternate screen.
    ///
    /// In inline mode, the UI is anchored at the bottom of the terminal and logs/progress
    /// can scroll above it.
    #[arg(long)]
    inline: bool,

    /// Load additional signature patterns
    #[arg(long)]
    signatures: Option<String>,

    /// Include signed community signatures
    #[arg(long)]
    community_signatures: bool,

    /// Only consider processes older than threshold (seconds)
    #[arg(long)]
    min_age: Option<u64>,

    /// Resource recovery goal for goal-oriented optimization
    #[arg(
        long,
        help = "Resource goal (e.g. 'free 4GB RAM') or pressure relief: relieve, cpu-pressure, mem-pressure, io-pressure"
    )]
    goal: Option<String>,

    /// TUI color theme (overrides environment detection)
    #[arg(long, value_parser = ["dark", "light", "high-contrast", "no-color"])]
    theme: Option<String>,

    /// Enable high-contrast mode (WCAG AAA). Shorthand for --theme=high-contrast.
    #[arg(long)]
    high_contrast: bool,

    /// Disable animations and use static indicators (accessibility).
    /// Also activatable via REDUCE_MOTION or PT_REDUCE_MOTION env vars.
    #[arg(long)]
    reduce_motion: bool,

    /// Enable screen-reader-friendly mode (text labels, verbose status, no animations).
    /// Also activatable via PT_ACCESSIBLE env var.
    #[arg(long)]
    accessible: bool,
}

#[derive(Args, Debug)]
struct ScanArgs {
    /// Force deep scan
    #[arg(long)]
    deep: bool,

    /// Number of samples to collect
    #[arg(long, default_value = "3")]
    samples: u32,

    /// Interval between samples (milliseconds)
    #[arg(long, default_value = "500")]
    interval: u64,

    /// Include kernel threads in scan output (default: exclude)
    #[arg(long)]
    include_kernel_threads: bool,

    /// Resource recovery goal (advisory only)
    #[arg(long)]
    goal: Option<String>,

    /// Record this quick scan and scoring observations privately (contains raw commands).
    /// The destination must not exist. Redact and review before sharing.
    #[arg(long, value_name = "PATH", conflicts_with = "deep")]
    record_replay: Option<PathBuf>,

    /// Activity window for replay recording in milliseconds (default: 500; 0 uses lifetime CPU).
    #[arg(
        long,
        requires = "record_replay",
        value_parser = clap::value_parser!(u64).range(0..=60_000)
    )]
    record_replay_window_ms: Option<u64>,

    /// Score a recorded census with current configuration, without inspecting live processes.
    /// Requires scoring observations from --record-replay. Never authorizes actions.
    #[arg(
        long,
        value_name = "PATH",
        conflicts_with_all = [
            "deep",
            "record_replay",
            "record_replay_window_ms",
            "goal",
            "include_kernel_threads",
            "samples",
            "interval"
        ]
    )]
    replay_scores: Option<PathBuf>,
}

