    #[test]
    fn memory_goal_credits_private_pages_without_rss_or_hugetlb() {
        let goal_str = "free 2MB RAM";
        let goal = parse_goal(goal_str).unwrap();
        let (mut candidates, plan) = fixture(&[(100, 8192, 0.0)]);
        let mut resources = memory_resources(&plan, &[(100, MIB)]);
        let observed = resources.private_memory.get_mut(&100).unwrap();
        observed.private_clean_bytes = MIB / 4;
        observed.private_dirty_bytes = 3 * MIB / 4;
        observed.private_hugetlb_bytes = Some(4096 * MIB);
        attach_goal_resource_observations(&mut candidates, &resources);
        let output = build_goal_plan_from_executable_actions(
            goal_str,
            &goal,
            0.0,
            &mut candidates,
            &plan,
            &resources,
        )
        .unwrap();
        assert!(!output.result.feasible);
        assert_eq!(output.result.total_contributions, [1.0]);
        assert_eq!(output.result.goal_achievement[0].shortfall, 1.0);
        assert_eq!(candidates[0]["memory_mb"], 8192);
        let evidence = &candidates[0]["goal_resources"];
        assert_eq!(evidence["memory_basis"], "private_clean_plus_private_dirty");
        assert_eq!(evidence["private_memory_bytes"], MIB);
        assert_eq!(
            evidence["private_memory"]["identity"],
            serde_json::json!(plan.actions[0].target)
        );
        assert_eq!(evidence["private_memory"]["private_clean_bytes"], MIB / 4);
        assert_eq!(
            evidence["private_memory"]["private_dirty_bytes"],
            3 * MIB / 4
        );
        assert_eq!(
            evidence["private_memory"]["private_hugetlb_bytes"],
            4096 * MIB
        );
        let summary = goal_summary_json(goal_str, &goal, &output);
        let measurement = &summary["resource_observations"]["memory"];
        assert_eq!(measurement["basis"], "private_clean_plus_private_dirty");
        assert_eq!(measurement["source"], "proc_pid_smaps_rollup");
        assert_eq!(measurement["unit"], "MiB");
        assert_eq!(measurement["guaranteed_recovery"], false);
        assert_eq!(
            measurement["excludes"],
            serde_json::json!(["shared_pages", "swap", "private_hugetlb"])
        );
    }

    #[test]
    fn memory_goal_preserves_fractional_mib_from_measured_bytes() {
        let goal_str = "free 1.5MB RAM";
        let goal = parse_goal(goal_str).unwrap();
        // The display is rounded to whole MiB; recovery keeps the measured bytes.
        let (mut candidates, plan) = fixture(&[(100, 1, 0.0)]);
        let resources = memory_resources(&plan, &[(100, MIB + MIB / 2)]);
        attach_goal_resource_observations(&mut candidates, &resources);
        let output = build_goal_plan_from_executable_actions(
            goal_str,
            &goal,
            0.0,
            &mut candidates,
            &plan,
            &resources,
        )
        .unwrap();
        assert!(output.result.feasible);
        assert_eq!(output.selected_pids, [100]);
        assert_eq!(output.result.total_contributions, [1.5]);
        assert_eq!(output.result.goal_achievement[0].shortfall, 0.0);
        assert_eq!(
            candidates[0]["goal_resources"]["private_memory_bytes"],
            MIB + MIB / 2
        );
        assert!(
            candidates[0]["goal_resources"]["private_memory"]["private_hugetlb_bytes"].is_null()
        );
    }

    #[test]
    fn memory_goal_requires_available_matching_private_measurements() {
        let goal_str = "free 100MB RAM";
        let goal = parse_goal(goal_str).unwrap();
        for case in ["missing", "uid", "start_id", "overflow"] {
            let (mut candidates, plan) = fixture(&[(100, 8192, 0.0)]);
            let mut resources = memory_resources(&plan, &[(100, 1000 * MIB)]);
            match case {
                "missing" => resources.private_memory.clear(),
                "uid" => resources.private_memory.get_mut(&100).unwrap().identity.uid += 1,
                "start_id" => resources
                    .private_memory
                    .get_mut(&100)
                    .unwrap()
                    .identity
                    .start_id
                    .0
                    .push_str("-reused"),
                "overflow" => {
                    let measured = resources.private_memory.get_mut(&100).unwrap();
                    measured.private_clean_bytes = u64::MAX;
                    measured.private_dirty_bytes = 1;
                }
                _ => unreachable!(),
            }
            attach_goal_resource_observations(&mut candidates, &resources);
            let output = build_goal_plan_from_executable_actions(
                goal_str,
                &goal,
                0.0,
                &mut candidates,
                &plan,
                &resources,
            )
            .unwrap();
            assert!(!output.result.feasible, "{case}");
            assert!(output.selected_pids.is_empty(), "{case}");
            assert_eq!(output.result.total_contributions, [0.0], "{case}");
            assert!(
                candidates[0]["goal_resources"]["private_memory_bytes"].is_null(),
                "{case}"
            );
            assert!(
                candidates[0]["goal_resources"]["private_memory"].is_null(),
                "{case}"
            );
        }
    }

    #[test]
    fn kill_memory_forecast_counts_unique_actual_unblocked_targets() {
        let (_, mut plan) = fixture(&[
            (100, 1000, 0.0),
            (200, 2000, 0.0),
            (300, 4000, 0.0),
            (400, 8000, 0.0),
        ]);
        let mut resources = memory_resources(
            &plan,
            &[
                (100, MIB + MIB / 2),
                (200, MIB / 2),
                (300, 4000 * MIB),
                (400, 8000 * MIB),
            ],
        );
        resources
            .private_memory
            .get_mut(&100)
            .unwrap()
            .private_hugetlb_bytes = Some(1000 * MIB);
        // The parent actually receiving the kill supplies the footprint, even
        // when the original zombie has a much larger observed allocation.
        plan.actions[1].routing = ActionRouting::ZombieToParent;
        plan.actions[1].original_zombie_target = Some(plan.actions[2].target.clone());
        plan.actions[2].blocked = true;
        plan.actions[3].action = Action::Pause;
        let mut repeated = plan.actions[0].clone();
        repeated.action_id = "repeated-stage-100".to_string();
        repeated.stage = 1;
        repeated.target.pgid = Some(1234);
        repeated.target.sid = Some(5678);
        plan.actions.push(repeated);

        assert_eq!(
            expected_private_memory_for_kills(&plan, &resources),
            Some(2 * MIB)
        );
    }

    fn prediction_activity(identity: &ProcessIdentity) -> pt_core::collect::ProcessActivity {
        pt_core::collect::ProcessActivity {
            pid: identity.pid.0,
            start_id: identity.start_id.clone(),
            uid: identity.uid,
            source: "procfs_window".into(),
            requested_window_ms: 500,
            cpu_percent: Some(400.0),
            cpu_ticks: Some(250),
            cpu_window_seconds: Some(0.5),
            io_window_seconds: None,
            read_bytes_per_second: None,
            write_bytes_per_second: None,
            io_active: None,
            cpu_error: None,
            io_error: None,
            pressure: None,
        }
    }

    #[test]
    fn saved_resource_forecasts_preserve_planning_counters_through_apply() {
        let (_, mut plan) = fixture(&[(100, 9000, 400.0)]);
        let mut resources = memory_resources(&plan, &[(100, MIB + MIB / 2)]);
        resources
            .private_memory
            .get_mut(&100)
            .unwrap()
            .private_hugetlb_bytes = Some(1000 * MIB);
        resources.processes.insert(
            100,
            ProcessGoalResources {
                identity: plan.actions[0].target.clone(),
                fd_count: 19,
            },
        );
        let pressure = PlanningPressure {
            cpu_usage: Some(pt_core::collect::pressure::HostCpuWindow {
                total_ticks: 1000,
                busy_ticks: 700,
                logical_cpus: 8,
                window_seconds: 1.0,
            }),
            ..Default::default()
        };
        let snapshot = build_resource_predictions(
            &plan,
            &resources,
            &pressure,
            PlanningResourceTimes {
                activity_unix_ms: 1000,
                private_memory_unix_ms: Some(2000),
                descriptors_unix_ms: Some(1500),
            },
            |identity| Some(prediction_activity(identity)),
        )
        .unwrap();
        assert_eq!(
            snapshot.actions[0]
                .memory
                .as_ref()
                .unwrap()
                .observed_at_unix_ms,
            2000
        );
        assert_eq!(
            snapshot.actions[0]
                .cpu
                .as_ref()
                .unwrap()
                .observed_at_unix_ms,
            1000
        );
        assert_eq!(
            snapshot.actions[0]
                .file_descriptors
                .as_ref()
                .unwrap()
                .observed_at_unix_ms,
            1500
        );

        // A later display footprint or measurement is not the saved forecast.
        plan.actions[0].rationale.memory_mb = Some(50_000.0);
        resources.private_memory.clear();
        resources.processes.clear();
        let mut document = serde_json::to_value(&plan).unwrap();
        document["resource_predictions"] = serde_json::to_value(&snapshot).unwrap();
        let canonical = serde_json::to_string(&document).unwrap();
        let parsed_plan = parse_agent_plan(&canonical).unwrap();
        let parsed_document = serde_json::from_str(&canonical).unwrap();
        let saved = saved_resource_predictions(&parsed_document, &parsed_plan)
            .unwrap()
            .unwrap();
        let expected = ExpectedGoalContribution::from_saved(
            &parsed_plan.actions[0],
            Some(&saved),
            "worker".into(),
        );
        assert_eq!(expected.memory_bytes, Some((MIB + MIB / 2) as f64));
        assert_eq!(expected.cpu_host_fraction, Some(0.25));
        assert_eq!(expected.file_descriptors, Some(19.0));
        assert_eq!(expected.ports, None);
        assert_eq!(saved.snapshot(), &snapshot);
    }

    #[test]
    fn resource_forecasts_reject_missing_or_changed_planning_evidence() {
        let (_, plan) = fixture(&[(100, 9000, 400.0)]);
        let mut resources = memory_resources(&plan, &[(100, MIB)]);
        resources.private_memory.get_mut(&100).unwrap().identity.uid += 1;
        resources.processes.insert(
            100,
            ProcessGoalResources {
                identity: resources.private_memory[&100].identity.clone(),
                fd_count: 900,
            },
        );
        let pressure = PlanningPressure::default();
        let snapshot = build_resource_predictions(
            &plan,
            &resources,
            &pressure,
            PlanningResourceTimes {
                activity_unix_ms: 1000,
                private_memory_unix_ms: Some(1000),
                descriptors_unix_ms: Some(1000),
            },
            |identity| {
                let mut activity = prediction_activity(identity);
                activity.source = "ps_lifetime_fallback".into();
                Some(activity)
            },
        )
        .unwrap();
        let prediction = &snapshot.actions[0];
        assert!(prediction.memory.is_none());
        assert!(prediction.cpu.is_none());
        assert!(prediction.file_descriptors.is_none());
        assert!(prediction
            .unavailable
            .iter()
            .any(|reason| reason.starts_with("memory:")));
        assert!(prediction
            .unavailable
            .iter()
            .any(|reason| reason.starts_with("cpu:")));

        let legacy = serde_json::to_value(&plan).unwrap();
        assert!(saved_resource_predictions(&legacy, &plan)
            .unwrap()
            .is_none());
        let expected =
            ExpectedGoalContribution::from_saved(&plan.actions[0], None, "legacy".into());
        assert!(expected.memory_bytes.is_none());
        assert!(expected.cpu_host_fraction.is_none());
        assert!(expected.file_descriptors.is_none());
        let mut malformed = legacy;
        malformed["resource_predictions"] = serde_json::json!({"schema_version": 999});
        assert!(saved_resource_predictions(&malformed, &plan).is_err());
    }

    #[test]
    fn planning_forecasts_follow_final_routed_target_and_action_kind() {
        let (_, mut plan) = fixture(&[(100, 1, 0.0), (200, 10000, 0.0), (300, 20000, 0.0)]);
        plan.actions[0].routing = ActionRouting::ZombieToParent;
        plan.actions[0].original_zombie_target = Some(plan.actions[1].target.clone());
        plan.actions[1].blocked = true;
        plan.actions[2].action = Action::Pause;
        let resources =
            memory_resources(&plan, &[(100, MIB), (200, 10000 * MIB), (300, 20000 * MIB)]);
        let snapshot = build_resource_predictions(
            &plan,
            &resources,
            &PlanningPressure::default(),
            PlanningResourceTimes {
                private_memory_unix_ms: Some(1000),
                ..Default::default()
            },
            |_| None,
        )
        .unwrap();
        assert_eq!(snapshot.actions.len(), 2);
        assert_eq!(snapshot.actions[0].target, plan.actions[0].target);
        assert_eq!(snapshot.actions[0].memory.as_ref().unwrap().bytes, MIB);
        assert_eq!(snapshot.actions[1].action, Action::Pause);
        assert!(snapshot.actions[1].memory.is_none());

        let saved = snapshot.validate(&plan).unwrap();
        for change in ["uid", "birth", "group", "action"] {
            let mut changed = plan.actions[0].clone();
            match change {
                "uid" => changed.target.uid += 1,
                "birth" => changed.target.start_id.0.push_str("-reused"),
                "group" => changed.target.pgid = Some(999),
                "action" => changed.action = Action::Restart,
                _ => unreachable!(),
            }
            let expected =
                ExpectedGoalContribution::from_saved(&changed, Some(&saved), change.into());
            assert!(expected.memory_bytes.is_none(), "{change}");
            assert!(expected.cpu_host_fraction.is_none(), "{change}");
            assert!(expected.file_descriptors.is_none(), "{change}");
        }
    }

