    #[test]
    fn planned_kill_budget_preserves_unselected_live_child() {
        let processes = vec![
            rec(100, 1, "sh", ProcessState::Sleeping),
            rec(101, 100, "sleep 600", ProcessState::Sleeping),
            rec(200, 1, "sleep 600", ProcessState::Sleeping),
        ];
        let mut policy = pt_core::config::Policy::default();
        policy.guardrails.max_kills_per_run = 1;
        for child in [
            None,
            Some(serde_json::json!({"pid": 101, "recommended_action": "keep"})),
        ] {
            let mut candidates = vec![cand(100), cand(200)];
            if let Some(child) = child {
                candidates.push(child);
            }
            let mut refs: Vec<_> = candidates.iter_mut().collect();
            apply_planned_kill_budget(&mut refs, &processes, &policy, false);
            assert_eq!(candidates[0]["recommended_action"], "review");
            assert_eq!(candidates[0]["tree_safety"]["rule"], "live_child");
            assert_eq!(candidates[1]["recommended_action"], "kill");
            if candidates.len() == 3 {
                assert_eq!(candidates[2]["recommended_action"], "keep");
            }
        }
    }

    #[test]
    fn executable_plan_preserves_final_safety_downgrades_and_canonical_identity() {
        use pt_core::decision::{decide_action, Action, ActionFeasibility};
        use pt_core::inference::ClassScores;
        use pt_core::plan::{DecisionCandidate, PreCheck};
        let policy = pt_core::config::Policy::default();
        let posterior = ClassScores {
            useful: 0.001,
            useful_bad: 0.0,
            abandoned: 0.999,
            zombie: 0.0,
        };
        let decision = decide_action(&posterior, &policy, &ActionFeasibility::allow_all()).unwrap();
        assert_eq!(decision.optimal_action, Action::Kill);
        let inputs = [100, 200, 300]
            .into_iter()
            .map(|pid| {
                let process = rec(pid, 1, "sleep 600", ProcessState::Sleeping);
                (
                    pid,
                    DecisionCandidate {
                        identity: process_identity_from_record(&process),
                        ppid: Some(1),
                        decision: decision.clone(),
                        blocked_reasons: Vec::new(),
                        stage_pause_before_kill: false,
                        process_state: Some(process.state),
                        parent_identity: None,
                        d_state_diagnostics: None,
                        supervisor_restart: None,
                    },
                )
            })
            .collect();
        let candidates = vec![
            cand(100),
            serde_json::json!({"pid": 200, "recommended_action": "review"}),
            serde_json::json!({"pid": 300, "recommended_action": "keep"}),
        ];
        let plan = build_agent_action_plan(
            &pt_common::SessionId::new(),
            &policy,
            &candidates,
            &inputs,
            "2026-10-04T12:00:00Z".to_string(),
        );
        assert_eq!(plan.actions.len(), 1);
        assert_eq!(plan.actions[0].target.pid.0, 100);
        assert_eq!(plan.actions[0].target.start_id.0, "b:1:100");
        assert!(plan.actions[0]
            .pre_checks
            .contains(&PreCheck::VerifyIdentity));
        assert!(plan.actions[0]
            .pre_checks
            .contains(&PreCheck::CheckDataLossGate));
        assert_eq!(plan.actions[0].rationale.posterior, Some(posterior));
        let mut document = serde_json::to_value(&plan).unwrap();
        document["candidates"] = serde_json::to_value(candidates).unwrap();
        let applied: pt_core::plan::Plan = serde_json::from_value(document).unwrap();
        assert_eq!(applied.plan_id, plan.plan_id);
        assert_eq!(applied.actions[0].action_id, plan.actions[0].action_id);
    }

    #[test]
    fn displayed_actions_match_stages_routed_targets_and_full_incarnations() {
        use pt_core::decision::{decide_action, Action, ActionFeasibility};
        use pt_core::inference::ClassScores;
        use pt_core::plan::DecisionCandidate;

        let policy = pt_core::config::Policy::default();
        let posterior = ClassScores {
            useful: 0.001,
            useful_bad: 0.0,
            abandoned: 0.999,
            zombie: 0.0,
        };
        let decision = decide_action(&posterior, &policy, &ActionFeasibility::allow_all()).unwrap();
        let parent = rec(900, 1, "parent", ProcessState::Sleeping);
        let inputs: std::collections::HashMap<_, _> = [100, 200, 300, 400, 500, 600, 700, 800]
            .into_iter()
            .map(|pid| {
                let state = if matches!(pid, 300 | 400) {
                    ProcessState::Zombie
                } else {
                    ProcessState::Sleeping
                };
                let process = rec(pid, 900, "sleep 600", state);
                let mut chosen = decision.clone();
                chosen.optimal_action = match pid {
                    200 => Action::Pause,
                    400 | 800 => Action::Restart,
                    600 => Action::Keep,
                    _ => Action::Kill,
                };
                (
                    pid,
                    DecisionCandidate {
                        identity: process_identity_from_record(&process),
                        ppid: Some(900),
                        decision: chosen,
                        blocked_reasons: if pid == 500 {
                            vec!["protected".to_string()]
                        } else {
                            Vec::new()
                        },
                        stage_pause_before_kill: pid == 100,
                        process_state: Some(state),
                        parent_identity: (pid == 300)
                            .then(|| process_identity_from_record(&parent)),
                        d_state_diagnostics: None,
                        supervisor_restart: None,
                    },
                )
            })
            .collect();
        let mut candidates: Vec<_> = [100, 200, 300, 400, 500, 600, 700, 800]
            .into_iter()
            .map(|pid| serde_json::json!({
                "pid": pid, "posterior": posterior,
                "recommended_action": match pid {
                    200 => "pause", 400 | 800 => "restart", 600 => "keep", 700 => "review", _ => "kill"
                },
                "action_rationale": "original evidence", "zombie_routing": {}
            }))
            .collect();
        let plan = build_agent_action_plan(
            &pt_common::SessionId::new(),
            &policy,
            &candidates,
            &inputs,
            "2026-10-05T12:00:00Z".to_string(),
        );
        reconcile_agent_action_candidates(&mut candidates, &inputs, &plan);
        assert_eq!(plan.actions.len(), 4);
        assert!(plan
            .actions
            .iter()
            .all(|action| !action.blocked && action.action != Action::Keep));
        assert_eq!(candidates[0]["recommended_action"], "kill");
        assert_eq!(
            candidates[0]["plan_action_ids"].as_array().unwrap().len(),
            2
        );
        assert_eq!(candidates[1]["recommended_action"], "pause");
        assert_eq!(candidates[2]["recommended_action"], "restart");
        assert_eq!(
            candidates[2]["action_target"],
            serde_json::to_value(process_identity_from_record(&parent)).unwrap()
        );
        for index in [3, 4, 6, 7] {
            assert_eq!(
                candidates[index]["recommended_action"], "review",
                "index {index}"
            );
            assert_eq!(
                candidates[index]["posterior"],
                serde_json::to_value(posterior).unwrap()
            );
        }
        assert_eq!(candidates[5]["recommended_action"], "keep");
        // Rebuilding after final output filtering preserves zombie Kill-to-
        // Restart routing, including the original zombie's incarnation.
        let rebuilt = build_agent_action_plan(
            &pt_common::SessionId(plan.session_id.clone()),
            &policy,
            &candidates,
            &inputs,
            "2026-10-05T12:00:00Z".to_string(),
        );
        assert_eq!(rebuilt.actions.len(), plan.actions.len());
        assert!(rebuilt.actions.iter().any(|action| {
            action.action == Action::Restart
                && action.target == process_identity_from_record(&parent)
                && action.original_zombie_target.as_ref() == Some(&inputs[&300].identity)
        }));
        let mut kill_only = candidates.clone();
        kill_only.retain(|candidate| super::candidate_matches_filter(candidate, "kill"));
        assert_eq!(kill_only.len(), 1);
        assert_eq!(kill_only[0]["pid"], 100);
        let filtered_plan = build_agent_action_plan(
            &pt_common::SessionId(plan.session_id.clone()),
            &policy,
            &kill_only,
            &inputs,
            "2026-10-05T12:00:00Z".to_string(),
        );
        assert_eq!(filtered_plan.actions.len(), 2);
        assert!(filtered_plan
            .actions
            .iter()
            .all(|action| action.target.pid.0 == 100));
        let recommended = super::agent_recommended_actions(&plan);
        assert_eq!(recommended.len(), plan.actions.len());
        for (recorded, action) in recommended.iter().zip(&plan.actions) {
            assert_eq!(recorded["pid"], action.target.pid.0);
            assert_eq!(
                recorded["action"],
                serde_json::to_value(action.action).unwrap()
            );
            assert_eq!(recorded["stage"], action.stage);
            assert_eq!(recorded["action_id"], action.action_id);
        }
        // Same PID with a different birth, owner or group cannot claim the old
        // executable action. The plan and its original evidence remain intact.
        for changed in ["birth", "owner", "group"] {
            let mut changed_inputs = inputs.clone();
            let identity = &mut changed_inputs.get_mut(&100).unwrap().identity;
            match changed {
                "birth" => identity.start_id = StartId::from_linux("b", 2, 100),
                "owner" => identity.uid = 1001,
                "group" => identity.pgid = Some(101),
                _ => unreachable!(),
            }
            let mut reused = vec![cand(100)];
            reconcile_agent_action_candidates(&mut reused, &changed_inputs, &plan);
            assert_eq!(reused[0]["recommended_action"], "review", "{changed}");
            assert_eq!(plan.actions.len(), 4);
        }
    }

    #[test]
    fn inactive_recommendations_do_not_probe_supervision() {
        let process = rec(900, 500, "worker", ProcessState::Sleeping);
        for initial in ["keep", "review"] {
            let mut action = initial;
            let mut rationale = "existing verdict".to_string();
            let target = super::finalize_candidate_remedy(
                &process,
                None,
                &mut action,
                &mut rationale,
                |_| panic!("an inactive recommendation must not collect more evidence"),
            );
            assert_eq!(action, initial);
            assert_eq!(rationale, "existing verdict");
            assert!(target.is_none());
        }
    }

    #[test]
    fn zombie_recommendations_check_and_target_the_parent_incarnation() {
        let zombie = rec(900, 500, "defunct worker", ProcessState::Zombie);
        let parent = rec(500, 10, "worker supervisor", ProcessState::Sleeping);
        let expected = process_identity_from_record(&parent);
        for initial in ["kill", "restart"] {
            let mut action = initial;
            let mut rationale = "expected-loss remedy".to_string();
            let target = super::finalize_candidate_remedy(
                &zombie,
                Some(&parent),
                &mut action,
                &mut rationale,
                |identity| {
                    assert_eq!(identity, &expected);
                    assert_ne!(identity, &process_identity_from_record(&zombie));
                    Ok(())
                },
            );
            assert_eq!(action, "restart");
            assert_eq!(target, Some(expected.clone()));
            assert!(rationale.contains("zombie PID 900 is already dead"));
            assert!(rationale.contains("parent PID 500"));
        }
    }

    #[test]
    fn zombie_policy_evidence_uses_the_actual_parent_only_for_routed_actions() {
        use pt_core::decision::Action;

        let zombie = rec(900, 500, "defunct worker", ProcessState::Zombie);
        let parent = rec(500, 10, "worker supervisor", ProcessState::Sleeping);
        let mut live = zombie.clone();
        live.state = ProcessState::Sleeping;
        for action in [Action::Kill, Action::Restart] {
            let subject =
                super::candidate_policy_evidence_subject(&zombie, Some(&parent), action).unwrap();
            assert!(std::ptr::eq(subject, &parent));
            assert_eq!(
                process_identity_from_record(subject),
                process_identity_from_record(&parent)
            );
            let direct =
                super::candidate_policy_evidence_subject(&live, Some(&parent), action).unwrap();
            assert!(std::ptr::eq(direct, &live));
        }
        // Keep/recovery/advice paths retain their own subject without requiring
        // an unrelated parent's descriptors or creating a destructive route.
        for action in [
            Action::Keep,
            Action::Renice,
            Action::Pause,
            Action::Resume,
            Action::Freeze,
            Action::Unfreeze,
        ] {
            let subject = super::candidate_policy_evidence_subject(&zombie, None, action).unwrap();
            assert!(std::ptr::eq(subject, &zombie));
        }
    }

    #[test]
    fn zombie_policy_evidence_refuses_unusable_routes_before_probing() {
        use pt_core::decision::Action;

        let zombie = rec(900, 500, "defunct worker", ProcessState::Zombie);
        let parent = rec(500, 10, "worker supervisor", ProcessState::Sleeping);
        for case in [
            "missing",
            "wrong_parent",
            "init",
            "self_parent",
            "zombie_parent",
            "dead_parent",
            "unknown_parent",
            "missing_parent_birth",
            "foreign_parent_birth",
            "unknown_parent_boot",
            "synthetic_parent_boot",
            "unknown_source_boot",
            "foreign_source_birth",
        ] {
            let mut source = zombie.clone();
            let mut target = parent.clone();
            match case {
                "wrong_parent" => target.pid = pt_common::ProcessId(600),
                "init" => {
                    source.ppid = pt_common::ProcessId(1);
                    target = rec(1, 0, "init", ProcessState::Sleeping);
                }
                "self_parent" => {
                    source.ppid = source.pid;
                    target = source.clone();
                    target.state = ProcessState::Sleeping;
                }
                "zombie_parent" => target.state = ProcessState::Zombie,
                "dead_parent" => target.state = ProcessState::Dead,
                "unknown_parent" => target.state = ProcessState::Unknown,
                "missing_parent_birth" => target.start_id = StartId(String::new()),
                "foreign_parent_birth" => target.start_id = StartId::from_linux("b", 1, 600),
                "unknown_parent_boot" => target.start_id = StartId::from_linux("unknown", 1, 500),
                "synthetic_parent_boot" => {
                    target.start_id = StartId::from_macos("synthetic", 1, 500);
                }
                "unknown_source_boot" => source.start_id = StartId::from_linux("unknown", 1, 900),
                "foreign_source_birth" => source.start_id = StartId::from_linux("b", 1, 901),
                _ => {}
            }
            for action in [Action::Kill, Action::Restart] {
                let subject = super::candidate_policy_evidence_subject(
                    &source,
                    (case != "missing").then_some(&target),
                    action,
                );
                assert!(subject.is_err(), "{case}: {action:?}");
                assert!(subject.unwrap_err().contains("usable parent identity"));
            }
        }
    }

    #[test]
    fn zombie_recommendations_refuse_missing_wrong_and_init_parents() {
        let zombie = rec(900, 500, "defunct worker", ProcessState::Zombie);
        let wrong = rec(600, 10, "unrelated", ProcessState::Sleeping);
        let init_zombie = rec(901, 1, "defunct worker", ProcessState::Zombie);
        let init = rec(1, 0, "init", ProcessState::Sleeping);
        for (process, parent) in [
            (&zombie, None),
            (&zombie, Some(&wrong)),
            (&init_zombie, Some(&init)),
        ] {
            let mut action = "kill";
            let mut rationale = "expected-loss remedy".to_string();
            let target = super::finalize_candidate_remedy(
                process,
                parent,
                &mut action,
                &mut rationale,
                |_| panic!("no usable target exists to probe"),
            );
            assert_eq!(action, "review");
            assert!(target.is_none());
            assert!(rationale.contains("usable parent identity"));
        }
    }

    #[test]
    fn unavailable_supervision_refuses_direct_and_routed_remedies() {
        let parent = rec(500, 10, "parent", ProcessState::Sleeping);
        for (state, initial) in [
            (ProcessState::Sleeping, "kill"),
            (ProcessState::Sleeping, "pause"),
            (ProcessState::Zombie, "kill"),
            (ProcessState::Zombie, "restart"),
        ] {
            let process = rec(900, 500, "worker", state);
            let mut action = initial;
            let mut rationale = "expected-loss remedy".to_string();
            let target = super::finalize_candidate_remedy(
                &process,
                Some(&parent),
                &mut action,
                &mut rationale,
                |identity| {
                    assert_eq!(identity.pid.0, if state.is_zombie() { 500 } else { 900 });
                    Err("mandatory supervision evidence is unavailable".to_string())
                },
            );
            assert_eq!(action, "review");
            assert!(target.is_none());
            assert!(rationale.contains("mandatory supervision evidence is unavailable"));
        }
    }

    #[cfg(target_os = "linux")]
